package jp.tapmarker;
import java.util.*;
public class MainLoopBranchTest {
 static int n;static void check(boolean b,String label){if(!b)throw new AssertionError(label);n++;System.out.println("PASS "+label);}
 static PhaseEngine.Watch match(String id,String region,String next){PhaseEngine.Watch w=new PhaseEngine.Watch();w.id=id;w.regionId=region;w.condition=PhaseEngine.MATCH;w.reference=new float[]{1};w.nextPhase=next;return w;}
 public static void main(String[] args){PhaseEngine e=new PhaseEngine();e.strictRuntime=true;PhaseEngine.Phase main=new PhaseEngine.Phase();main.id="main";PhaseEngine.Phase next=new PhaseEngine.Phase();next.id="next";e.phases.put(main.id,main);e.phases.put(next.id,next);PhaseEngine.Watch loop=match("loop","mainROI","main"),exit=match("exit","button","next");main.watches.add(loop);main.watches.add(exit);Map<String,float[]> samples=new HashMap<>();samples.put("mainROI",new float[]{1});samples.put("button",new float[]{0});e.enter("main",0);e.observe(samples,1);e.observe(samples,2);check(e.poll()==loop,"main operation selected while exit absent");e.finish(loop,3);samples.put("button",new float[]{1});e.observe(samples,4);check(e.awaitingBranch(),"first exit frame pauses continuous marker taps");check(e.poll()==null,"main loop cannot destroy exit before second confirmation");e.observe(samples,5);check(e.poll()==exit,"exit wins over simultaneously matching main loop");e.finish(exit,6);check(e.current.equals("next"),"exit operation completion changes actual state");check(e.poll()==null,"main queued actions do not survive transition");e.enter("main",10);exit.condition=PhaseEngine.CHANGE;samples.put("button",new float[]{0});e.observe(samples,11);e.observe(samples,12);check(e.poll()==loop,"loop starts after external change baseline established");e.finish(loop,13);samples.put("button",new float[]{1});e.observe(samples,14);check(e.poll()==null,"change candidate also pauses main loop");e.observe(samples,15);check(e.poll()==exit,"self loop preserves external change baseline");e.finish(exit,16);check(e.current.equals("next"),"change branch updates state");System.out.println("TOTAL "+n+" main-loop branching checks passed; device UI not tested.");}
}
